#!/usr/bin/env python3
from pathlib import Path
import re
import tempfile
import zipfile

root = Path(__file__).resolve().parents[1]
archive = root / "deyn-apk-project.zip"

with tempfile.TemporaryDirectory() as td:
    work = Path(td)
    with zipfile.ZipFile(archive) as z:
        z.extractall(work)

    page = work / "deyn-keygen/www/index.html"
    html = page.read_text(encoding="utf-8")
    original = html

    # The field is generated by the app markup and may not be a literal
    # input tag in the current archive. Replace the explicit 14-char limits
    # wherever they are expressed in HTML/JS.
    replacements = [
        (r'(?i)(maxlength\s*=\s*["\']?)14(["\']?)', r'\g<1>32\2'),
        (r'(?i)(maxLength\s*:\s*)14\b', r'\g<1>32'),
        (r'(?i)(maxLength\s*=\s*)14\b', r'\g<1>32'),
        (r'(?i)(maxlength\s*:\s*)14\b', r'\g<1>32'),
    ]
    counts = []
    for pattern, replacement in replacements:
        html, n = re.subn(pattern, replacement, html)
        counts.append(n)

    if sum(counts) == 0:
        # Look for the actual device ID field declaration and add a 32-char
        # maximum if the source uses a differently formatted attribute.
        candidates = list(re.finditer(r'<(?:input|textarea)\b[^>]*>', html, re.I | re.S))
        for m in candidates:
            tag = m.group(0)
            if re.search(r'(device|device.?id|معرف الجهاز|معرّف الجهاز)', tag, re.I):
                if re.search(r'maxlength', tag, re.I):
                    fixed = re.sub(r'(?i)(maxlength\s*=\s*["\']?)\d+', r'\g<1>32', tag, count=1)
                    html = html[:m.start()] + fixed + html[m.end():]
                    counts.append(1)
                    break

    if html == original:
        raise SystemExit("Could not locate a 14-character limit in Keygen source; refusing to build unchanged APK")

    # Ensure no explicit 14-character maximum remains.
    if re.search(r'(?i)maxlength\s*=\s*["\']?14\b|maxLength\s*[:=]\s*14\b', html):
        raise SystemExit("A 14-character maximum remains in Keygen source")

    page.write_text(html, encoding="utf-8")
    temp = archive.with_suffix(".zip.tmp")
    with zipfile.ZipFile(temp, "w", zipfile.ZIP_DEFLATED, compresslevel=9) as z:
        for f in sorted(work.rglob("*")):
            if f.is_file():
                z.write(f, f.relative_to(work).as_posix())
    temp.replace(archive)

print(f"PASS: expanded Keygen input limit to 32 chars (replacements={sum(counts)})")
